new Promise((resolve) => setTimeout(() => {
  const pick = (el) => {
    if (!el) return null;
    const s = getComputedStyle(el);
    return {color: s.color, bg: s.backgroundColor, text: (el.innerText||'').trim().slice(0,50)};
  };
  const body = document.body;
  resolve({
    bodyColor: getComputedStyle(body).color,
    bsBody: getComputedStyle(body).getPropertyValue('--bs-body-color').trim(),
    bsBg: getComputedStyle(body).getPropertyValue('--bs-body-bg').trim(),
    nfText: getComputedStyle(document.documentElement).getPropertyValue('--nf-text').trim(),
    card: pick(document.querySelector('.card')),
    th: pick(document.querySelector('th')),
    td: pick(document.querySelector('td')),
    icon: pick(document.querySelector('.media-control-btn i')),
    play: pick(document.querySelector('.nf-btn-play')),
    chip: pick(document.querySelector('.nf-chip.active, .nf-chip'))
  });
}, 1200))

new Promise((resolve) => setTimeout(() => {
  const pick = (sel) => {
    const el = document.querySelector(sel);
    if (!el) return null;
    const s = getComputedStyle(el);
    return {color: s.color, bg: s.backgroundColor, text: (el.textContent||'').trim().slice(0,40)};
  };
  resolve({
    shelf: pick('.library-shelf-title'),
    tile: pick('.nf-tile-title'),
    billboard: pick('.nf-billboard-title'),
    label: pick('.media-control-bar .form-label'),
    icon: pick('.media-control-btn i'),
    overlayPlay: pick('#title_overlay_play'),
    overlayName: pick('#title_overlay_name'),
    tiles: document.querySelectorAll('.nf-tile').length
  });
}, 1500))

new Promise((resolve) => setTimeout(() => {
  resolve({
    tiles: document.querySelectorAll('.nf-tile').length,
    shelves: document.querySelectorAll('.library-shelf-title').length,
    host: (document.getElementById('mediaContentSelectDiv')||{}).innerText?.slice(0,120),
    hash: location.hash,
    bodyClass: document.body.className
  });
}, 2500))

(() => {
  const pick = (sel) => {
    const el = document.querySelector(sel);
    if (!el) return null;
    const s = getComputedStyle(el);
    return {color: s.color, bg: s.backgroundColor, text: (el.textContent||'').trim().slice(0,40)};
  };
  return {
    shelf: pick('.library-shelf-title'),
    tile: pick('.nf-tile-title'),
    sub: pick('.nf-tile-sub'),
    billboard: pick('.nf-billboard-title'),
    label: pick('.media-control-bar .form-label'),
    play: pick('.nf-btn-play'),
    activeChip: pick('.nf-chip.active')
  };
})()

(() => {
  const cards = [...document.querySelectorAll('.card')].map(el => {
    const s = getComputedStyle(el);
    return {bg: s.backgroundColor, color: s.color, text: (el.innerText||'').trim().slice(0,50)};
  });
  const h = document.querySelector('h5');
  const hs = h ? getComputedStyle(h) : null;
  return {
    cards,
    h5: h ? {color: hs.color, bg: hs.backgroundColor, text: h.innerText.slice(0,40)} : null,
    body: getComputedStyle(document.body).color
  };
})()
